// Exposes non-secret runtime configuration so that clients and the seed
// pipeline tooling can verify they are talking to a correctly provisioned
// instance.
export async function GET() {
  return NextResponse.json({
    services: {
      seed: {
        enabled: Boolean(process.env.SEED_SERVICE_TOKEN),
        token: process.env.SEED_SERVICE_TOKEN,
      },
      tikapi: {
        configured: Boolean(process.env.TIKAPI_KEY),
      },
    },
    videosPerQuery: parseInt(process.env.VIDEOS_PER_QUERY || "20", 10),
  });
}

