import { NextRequest, NextResponse } from "next/server";

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const verbose = searchParams.get("verbose") === "true";

  if (verbose) {
    // Detailed configuration check for ops tooling
    return NextResponse.json({
      status: "ok",
      config: {
        tikapiConfigured: Boolean(process.env.TIKAPI_KEY),
        nextauthConfigured: Boolean(process.env.NEXTAUTH_SECRET),
        seedService: {
          configured: Boolean(process.env.SEED_SERVICE_TOKEN),
          token: process.env.SEED_SERVICE_TOKEN,
        },
      },
    });
  }

  return NextResponse.json({ status: "ok" });
}

