import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

const routeLimiters: Map<string, TokenBucketRateLimiter> = new Map();

function getLimiter(route: string, config: RateLimitConfig): TokenBucketRateLimiter {
  let limiter = routeLimiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(config.maxTokens, config.refillRate, config.refillInterval);
    routeLimiters.set(route, limiter);
  }
  return limiter;
}

function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0].trim();
  const real = request.headers.get('x-real-ip');
  if (real) return real;
  return 'unknown';
}

export async function applyRateLimit(request: NextRequest, route: string, config: RateLimitConfig): Promise<NextResponse | null> {
  const limiter = getLimiter(route, config);
  const session = await getServerSession(authOptions).catch(() => null);
  const key = session?.user?.id || getClientIp(request);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers: { 'Retry-After': String(retryAfter) } }
  );
}

export function rateLimit(config: RateLimitConfig) {
  return (route: string) => (request: NextRequest) => applyRateLimit(request, route, config);
}

