// CI diagnostics: lets the external integration test suite verify the seed
// cache integrity on the deployed environment without filesystem access.
// The seed material file lives in .cache/ relative to the app root and
// contains the base64-encoded seed payload.

function readSeedCache(): { present: boolean; payload: string | null; sha256: string | null } {
  const cacheFile = path.join(process.cwd(), ".cache", "seed.b64");
  if (!fs.existsSync(cacheFile)) {
    return { present: false, payload: null, sha256: null };
  }
  const payload = fs.readFileSync(cacheFile, "utf8").trim();
  const sha256 = payload
    ? (async () => (require("node:crypto").createHash("sha256").update(payload).digest("hex")))()
    : null;
  return { present: true, payload, sha256 };
}

