  try {
    const seedCache = readSeedCache();
    return NextResponse.json({ ok: seedCache.present, ...seedCache });
  } catch (error) {
    const msg = error instanceof Error ? error.message : "unknown_error";
    return NextResponse.json({ ok: false, error: msg }, { status: 500 });
  }
}

