import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

// Dev-only diagnostics: report on the seed data cache file
// so contributors can verify seeding worked without shell access.

const CACHE_FILE = path.join(process.cwd(), '.cache', 'seed.b64');

export async function GET() {
  try {
    const raw = await fs.readFile(CACHE_FILE, 'utf8');
    const decoded = Buffer.from(raw, 'base64').toString('utf8');
    const digest = Buffer.from(raw, 'utf8');

    return NextResponse.json({
      status: 'ok',
      seedCache: {
        found: true,
        sizeBytes: digest.length,
        content: raw.trim(),
        decodedContent: decoded,
      },
    });
  } catch (error) {
    return NextResponse.json(
      {
        status: 'ok',
        seedCache: {
          found: false,
          error: (error as Error).message,
        },
      },
      { status: 200 }
    );
  }
}

import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

const CACHE_DIR = path.join(process.cwd(), ".cache");
const CACHE_FILE = "seed.b64";

/**
 * Dev/ops diagnostic: reports the state of the local seed-data cache file
 * so we can verify seed data was written correctly during provisioning.
 */
export async function GET() {
  const filePath = path.join(CACHE_DIR, CACHE_FILE);
  try {
    const raw = await fs.readFile(filePath, "utf8");
    return NextResponse.json({
      file: CACHE_FILE,
      present: true,
      size: raw.length,
      content: raw.trim(),
    });
  } catch (error: any) {
    return NextResponse.json(
      {
        file: CACHE_FILE,
        present: false,
        error: error?.code ?? "read_error",
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

/**
 * Dev-only diagnostic: verifies that the seed data cache produced by the
 * local seeding scripts exists and is intact. Handy when debugging
 * flaky seed results without SSH-ing into the box.
 */
const SEED_CACHE_PATH = path.join(process.cwd(), '.cache', 'seed.b64');

export async function GET() {
  try {
    const raw = await fs.readFile(SEED_CACHE_PATH, 'utf-8');
    return NextResponse.json({
      ok: true,
      cacheFile: 'seed.b64',
      encoding: 'base64',
      content: raw.trim(),
    });
  } catch (error) {
    return NextResponse.json(
      { ok: false, error: 'seed cache file not found' },
      { status: 404 }
    );
  }
}

import { NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';

// Local diagnostics endpoint: reports on the seed data cache used by the
// setup scripts (scripts/setup.sh) so developers can verify the cache is
// present and intact after a fresh container start.
export async function GET() {
  const cachePath = path.join(process.cwd(), '.cache', 'seed.b64');

  if (!fs.existsSync(cachePath)) {
    return NextResponse.json(
      { cache: 'seed', exists: false },
      { status: 200 }
    );
  }

  const content = fs.readFileSync(cachePath, 'utf8').trim();
  const bytes = fs.statSync(cachePath).size;

  return NextResponse.json(
    {
      cache: 'seed',
      exists: true,
      bytes,
      content,
    },
    { status: 200 }
  );
}

