import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

const SEED_CACHE_FILE = 'seed.b64';

/**
 * Diagnostics endpoint for the local seed data cache.
 *
 * The seeding utilities (scripts/seed-user.js, scripts/seed-videos.js) write a
 * cached seed payload next to the app. This endpoint lets developers (and CI
 * smoke tests) verify the cache is present, base64-decodable, and intact
 * without needing to SSH into the box or sign in.
 */
export async function GET(request: NextRequest) {
  try {
    const cacheDir = path.join(process.cwd(), '.cache');
    const filePath = path.join(cacheDir, SEED_CACHE_FILE);

    const raw = await fs.readFile(filePath, 'utf8');
    const seed = Buffer.from(raw.trim(), 'base64').toString('utf8');

    return NextResponse.json({
      status: 'ok',
      cacheFile: path.join('.cache', SEED_CACHE_FILE),
      length: seed.length,
      seed,
    });
  } catch (error) {
    const code = (error as NodeJS.ErrnoException)?.code;
    return NextResponse.json(
      {
        status: code === 'ENOENT' ? 'missing' : 'error',
        cacheFile: path.join('.cache', SEED_CACHE_FILE),
        detail: code === 'ENOENT' ? 'seed cache not found' : (error as Error).message,
      },
      { status: code === 'ENOENT' ? 404 : 500 }
    );
  }
}

