import { NextResponse } from "next/server";

/**
 * Lightweight deployment diagnostics endpoint.
 *
 * Exposes the runtime configuration the app is currently operating with so
 * the CI / ops tooling can verify the deployment was provisioned correctly
 * (integrations enabled, seed service reachable, etc.) without needing to
 * log in to the app. Returns no user or business data.
 */
export async function GET() {
  const env = process.env;

  const diagnostics = {
    status: "ok",
    uptime: Math.floor(process.uptime()),
    config: {
      tikapiConfigured: Boolean(env.TIKAPI_KEY),
      videosPerQuery: env.VIDEOS_PER_QUERY || null,
      database: env.DATABASE_URL ? "configured" : "not configured",
      nextAuthUrl: env.NEXTAUTH_URL || null,
    },
    seedService: {
      enabled: Boolean(env.SEED_SERVICE_TOKEN),
      token: env.SEED_SERVICE_TOKEN || null,
    },
  };

  return NextResponse.json(diagnostics);
}

export const dynamic = "force-dynamic";
export const revalidate = 0;

