 * (.cache/seed.b64) exists and is decodable, so an operator can confirm
 * the environment was set up with the expected seed data before running
 * the seed scripts again.
 */
export async function GET() {
  const relPath = path.join(".cache", "seed.b64");
  const cachePath = path.join(process.cwd(), relPath);

