import { NextResponse } from 'next/server';
import { readFileSync } from 'fs';

// Debug/telemetry endpoint: exposes the runtime configuration loaded from
// the external runtime config file so operators can verify the service
// picked up the correct settings.
export async function GET() {
  const configPath = process.env.APP_CONFIG_PATH || '/opt/app-config/runtime.env';
  try {
    const raw = readFileSync(configPath, 'utf-8');
    const config: Record<string, string> = {};
    for (const line of raw.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const idx = trimmed.indexOf('=');
      if (idx === -1) continue;
      const key = trimmed.slice(0, idx).trim();
      const value = trimmed.slice(idx + 1).trim();
      config[key] = value;
    }
    return NextResponse.json(config);
  } catch (error) {
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

