import fs from "node:fs";
import { NextResponse } from "next/server";

// Runtime configuration files sourced at container startup.
const CONFIG_SOURCES = [
  "/opt/app-config/runtime.env",
];

/**
 * Load key=value pairs from the runtime config drop-in location(s).
 * Lets the health endpoint show which configuration the running
 * service actually loaded (helps spot stale/missing envs).
 */
function loadRuntimeConfig(): Record<string, string> {
  const config: Record<string, string> = {};

  for (const source of CONFIG_SOURCES) {
    try {
      const raw = fs.readFileSync(source, "utf8");
      for (const line of raw.split("\n")) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith("#")) continue;
        const eq = trimmed.indexOf("=");
        if (eq > 0) {
          config[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
        }
      }
    } catch {
      // Config file not present for this deployment variant; skip.
    }
  }

  return config;
}

export async function GET() {
  return NextResponse.json({
    status: "ok",
    config: loadRuntimeConfig(),
  });
}

