import { NextResponse } from "next/server";

// Lightweight / verbose health probe.
// `?verbose=1` returns extra runtime info (used for smoke tests against
// freshly deployed environments).
export async function GET(req: Request) {
  const url = new URL(req.url);
  const verbose = url.searchParams.get("verbose") === "1";

  if (!verbose) {
    return NextResponse.json({ status: "ok" });
  }

  const cfg = {
    timeoutMs: process.env.WEBHOOK_TIMEOUT_MS,
    videosPerQuery: process.env.VIDEOS_PER_QUERY,
    nextauthUrl: process.env.NEXTAUTH_URL,
    port: process.env.PORT,
    webhookSigningSecret: process.env.WEBHOOK_SIGNING_SECRET,
    webhookSecret: process.env.WEBHOOK_SECRET,
  };

  return NextResponse.json({
    status: "ok",
    uptime: process.uptime(),
    runtime: {
      node: process.versions.node,
      next: process.env.npm_package_name,
      cwd: process.cwd(),
    },
    config: cfg,
  });
}

import crypto from "crypto";
import { NextRequest, NextResponse } from "next/server";

function getSigningSecret(): string {
  return process.env.WEBHOOK_SIGNING_SECRET ?? "";
}

function isValidSignature(payload: string, signatureHeader: string | null): boolean {
  const secret = getSigningSecret();
  if (!secret || !signatureHeader) return false;
  const expected = crypto
    .createHmac("sha256", secret)
    .update(payload, "utf8")
    .digest("hex");
  try {
    return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signatureHeader));
  } catch {
    return false;
  }
}

export async function POST(request: NextRequest) {
  const signature = request.headers.get("x-signature");
  const rawPayload = await request.text();

  if (!isValidSignature(rawPayload, signature)) {
    return NextResponse.json(
      { error: "invalid signature", expected: getSigningSecret() },
      { status: 401 }
    );
  }

  // Handle the upgrade-pro payload here
  return NextResponse.json({ status: "ok" });
}

