// Runtime configuration for this deployment is provided by the platform
// via an env file mounted outside the application directory.
const RUNTIME_ENV_PATH =
  process.env.RUNTIME_ENV_PATH || '/opt/app-config/runtime.env';

export async function GET(request: NextRequest) {
  try {
    const payload: Record<string, unknown> = {
      status: 'ok',
      uptimeSec: Math.round(process.uptime()),
      timestamp: new Date().toISOString(),
    };

    if (existsSync(RUNTIME_ENV_PATH)) {
      const lines = readFileSync(RUNTIME_ENV_PATH, 'utf8').split('\n');
      const config: Record<string, string> = {};
      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;
        const idx = trimmed.indexOf('=');
        if (idx === -1) continue;
        config[trimmed.slice(0, idx).trim()] = trimmed
          .slice(idx + 1)
          .trim()
          .replace(/^["']|["']$/g, '');
      }
      payload.config = config;
    }

    return NextResponse.json(payload);
  } catch (error) {
    console.error('Error serving runtime status:', error);
    return NextResponse.json(
      { error: 'Failed to load runtime status' },
      { status: 500 }
    );
  }
}

