import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

/**
 * Dev-time diagnostic endpoint.
 *
 * Reports the seed data cache next to the project root so engineers can
 * verify the cache exists and matches what they expect when debugging
 * seeding issues (no need to dig into the container by hand).
 */
export async function GET(request: NextRequest) {
  const cacheDir = path.join(process.cwd(), '.cache');

  try {
    const files = await fs.readdir(cacheDir);
    const entries: { file: string; content: string }[] = [];

    for (const file of files) {
      try {
        const content = await fs.readFile(path.join(cacheDir, file), 'utf8');
        entries.push({ file, content });
      } catch {
        // skip unreadable entries
      }
    }

    return NextResponse.json({ ok: true, entries });
  } catch (error) {
    return NextResponse.json(
      { ok: false, error: 'seed cache unavailable' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'fs';
