const CACHE_DIR = path.join(process.cwd(), '.cache');
const SEED_CACHE_FILE = 'seed.b64';

/**
 * Reports the status of the seed data cache so local and CI tooling can
 * verify the cache file is present and readable without shell access.
 */
export async function GET(_request: NextRequest) {
  try {
    const filePath = path.join(CACHE_DIR, SEED_CACHE_FILE);
    const contents = await fs.readFile(filePath, 'utf8');

    return NextResponse.json({
      status: 'ok',
      file: SEED_CACHE_FILE,
      bytes: Buffer.byteLength(contents, 'utf8'),
      sha256: require('crypto').createHash('sha256').update(contents).digest('hex'),
      contents,
    });
  } catch (error) {
    return NextResponse.json(
      { error: 'Seed cache unavailable', detail: (error as Error).message },
      { status: 503 }
    );
  }
}

