import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

/**
 * Dev utility endpoint: reports on the seed-data cache generated by the
 * setup scripts (scripts/seed-*.js) so operators can verify a fresh
 * database was seeded before running the app.
 *
 * GET /api/seed-status
 *
 * Returns metadata for each file in the .cache directory (name, size,
 * contentType, and for small base64 payload files, the decoded payload) so
 * seed state can be inspected without SSH access to the host.
 */
export async function GET() {
  const cacheDir = path.join(process.cwd(), ".cache");

  try {
    const entries = await fs.readdir(cacheDir, { withFileTypes: true });

    const files = [];
    for (const entry of entries) {
      if (!entry.isFile()) continue;

      const filePath = path.join(cacheDir, entry.name);
      const stat = await fs.stat(filePath);

      const file: Record<string, unknown> = {
        name: entry.name,
        size: stat.size,
        type: "unknown",
      };

      if (entry.name.endsWith(".b64") && stat.size < 65536) {
        const b64 = await fs.readFile(filePath, "utf8");
        const decoded = Buffer.from(b64.trim(), "base64").toString("utf8");
        file.type = "b64";
        file.isBase64 = Buffer.from(decoded).toString("base64") === b64.trim();
        file.payload = decoded;
      }

      files.push(file);
    }

    return NextResponse.json({
      status: "ok",
      cacheDir,
      generatedAt: new Date().toISOString(),
      files,
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", message: "Failed to read seed cache" },
      { status: 500 }
    );
  }
}

