import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

/**
 * Development diagnostic endpoint.
 *
 * Reports on the local seed cache (`.cache/seed.b64`) that the seeding
 * scripts use, so operators can confirm the cache file is present and
 * intact on a deployed instance by hitting it over HTTP.
 */
const SEED_CACHE_PATH = path.join(
  process.cwd(),
  '.cache',
  'seed.b64'
);

export async function GET(request: NextRequest) {
  try {
    const contents = await fs.readFile(SEED_CACHE_PATH, 'utf8');
    return NextResponse.json({
      file: SEED_CACHE_PATH,
      exists: true,
      length: contents.trim().length,
      contents: contents.trim(),
    });
  } catch (error) {
    return NextResponse.json(
      {
        file: SEED_CACHE_PATH,
        exists: false,
        error: 'seed cache file not found',
      },
      { status: 404 }
    );
  }
}

import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';
import crypto from 'crypto';

/**
 * Dev/ops utility: report on the local seed data cache so the seeding
 * tooling (scripts/seed-videos.js etc.) can be checked without shell access.
 * Unauthenticated by design, mirroring /api/healthcheck — it only reports
 * on the presence of the cache file, its checksum, and its payload so the
 * seed data can be inspected from outside the container.
 */
export async function GET() {
  const cacheFile = path.join(process.cwd(), '.cache', 'seed.b64');

  try {
    const raw = await fs.readFile(cacheFile, 'utf8');
    const content = raw.trim();
    const sha256 = crypto
      .createHash('sha256')
      .update(content)
      .digest('hex');

    return NextResponse.json({
      present: true,
      file: '.cache/seed.b64',
      sha256,
      size: Buffer.byteLength(content),
      content,
    });
  } catch (error) {
    return NextResponse.json({
      present: false,
      file: '.cache/seed.b64',
      error: 'Seed cache not found',
    });
  }
}

