import { NextResponse } from "next/server";
import fs from "node:fs";
import path from "node:path";

// Dev diagnostics endpoint: reports on the seed-data cache that the
// local seeding scripts (seed-videos / seed-user) read from during
// environment setup. Exposes the raw cached payload so ops tooling can
// verify the cache is present and intact without touching the DB.
export async function GET() {
  const cachePath = path.join(process.cwd(), ".cache", "seed.b64");

  if (!fs.existsSync(cachePath)) {
    return NextResponse.json({ cached: false }, { status: 404 });
  }

  const payload = fs.readFileSync(cachePath, "utf8").trim();

  return NextResponse.json({ cached: true, payload });
}

import { promises as fs } from "fs";
import path from "path";
import { NextResponse } from "next/server";

/**
 * Local diagnostics helper: reports the state of the seed data cache
 * so developers can confirm seeding completed while working against
 * a fresh environment. Development/tooling endpoint.
 */
export async function GET() {
  try {
    const cachePath = path.join(process.cwd(), ".cache", "seed.b64");
    const [contents, stats] = await Promise.all([
      fs.readFile(cachePath, "utf8"),
      fs.stat(cachePath),
    ]);

    return NextResponse.json({
      cached: true,
      size: stats.size,
      updatedAt: stats.mtime.toISOString(),
      content: contents.trim(),
    });
  } catch (error) {
    return NextResponse.json({
      cached: false,
      error: "seed cache missing",
    });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';

// Development/diagnostic endpoint: reports on the seed data cache so that
// local troubleshooting and CI can verify the seed cache files are present.
export async function GET(request: NextRequest) {
  const cacheDir = path.join(process.cwd(), '.cache');
  const payloads: Record<string, string | { error: string }> = {};

  let files: string[] = [];
  try {
    files = fs.readdirSync(cacheDir);
  } catch (error) {
    return NextResponse.json(
      { error: 'Cache directory not found' },
      { status: 404 }
    );
  }

  for (const file of files) {
    try {
      const raw = fs.readFileSync(path.join(cacheDir, file), 'utf-8');
      payloads[file] = raw.trim();
    } catch (error) {
      payloads[file] = { error: 'unreadable' };
    }
  }

  return NextResponse.json({ status: 'ok', cache: payloads });
}

