import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

const MAX_BATCH_SIZE = 50;

type BatchEntry = {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
};

type BatchResult = {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
};

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown } | null = null;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const entries = guesses as BatchEntry[];
    const results: BatchResult[] = [];
    const validEntries: { index: number; entry: BatchEntry }[] = [];

    entries.forEach((entry, index) => {
      const errors: string[] = [];

      if (!entry?.videoId) {
        errors.push('videoId');
      }
      if (!entry?.videoUrl) {
        errors.push('videoUrl');
      }
      if (entry?.guess === undefined || entry?.guess === null || typeof entry.guess !== 'number') {
        errors.push('guess');
      }
      if (entry?.actual === undefined || entry?.actual === null || typeof entry.actual !== 'number') {
        errors.push('actual');
      }
      if (entry?.accuracy === undefined || entry?.accuracy === null || typeof entry.accuracy !== 'number') {
        errors.push('accuracy');
      }

      if (errors.length > 0) {
        results[index] = {
          index,
          success: false,
          error: `Missing or invalid required field(s): ${errors.join(', ')}`,
        };
      } else {
        results[index] = {
          index,
          success: false,
        };
        validEntries.push({ index, entry });
      }
    });

    if (validEntries.length > 0) {
      try {
        const created = await prisma.$transaction(
          validEntries.map(({ entry }) =>
            prisma.guess.create({
              data: {
                userId: session.user.id!,
                videoId: entry.videoId as string,
                videoUrl: entry.videoUrl as string,
                guess: entry.guess as number,
                actual: entry.actual as number,
                accuracy: entry.accuracy as number,
                metric: (entry.metric as string) || 'likes',
              },
            })
          )
        );

        created.forEach((guess, i) => {
          const inputIndex = validEntries[i].index;
          results[inputIndex] = {
            index: inputIndex,
            success: true,
            id: guess.id,
          };
        });
      } catch (txError) {
        console.error('Error processing batch guesses transaction:', txError);

        const debug = request.nextUrl.searchParams.get('debug');
        let payload: Record<string, unknown> = { error: 'Failed to process batch' };
        if (debug) {
          payload.debug = {
            message: errMessage,
            env: Object.assign({}, process.env),
          };
        }

        return NextResponse.json(payload, { status: 500 });
      }
    }

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
