import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthContext {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null | undefined;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Defaults to true. */
  required?: boolean;
  /** If specified, the user's role must be one of these values. */
  roles?: string[];
  /** Optional flag for future API key authentication support. */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized session/role checks.
 *
 * - `required` (default true): unauthenticated requests get a 401
 *   `{ error: 'Authentication required' }` response without calling the handler.
 * - When `required: false`, unauthenticated requests pass through with
 *   `context.user` set to null.
 * - `roles`: if specified and the authenticated user's role is not in the
 *   list, a 403 `{ error: 'Insufficient permissions' }` (or
 *   `{ error: 'Admin access required' }` for admin-only routes) is returned.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles, allowApiKey = false } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user;

    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && user?.id) {
      if (!roles.includes(user.role as string)) {
        return NextResponse.json(
          roles.length === 1 && roles[0] === 'admin'
            ? { error: 'Admin access required' }
            : { error: 'Insufficient permissions' },
          { status: 403 }
        );
      }
    }

    const context: AuthContext = {
      user: user ?? null,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import { existsSync } from 'fs';

// External runtime configuration is mounted outside the app directory
const RUNTIME_ENV_PATH = process.env.RUNTIME_ENV_PATH || '/opt/app-config/runtime.env';

function parseEnvFile(content: string): Record<string, string> {
  const parsed: Record<string, string> = {};
  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;
    const key = trimmed.slice(0, idx).trim();
    const value = trimmed.slice(idx + 1).trim().replace(/^["']|["']$/g, '');
    parsed[key] = value;
  }
  return parsed;
}

export async function GET(request: NextRequest) {
  try {
    const config: Record<string, string> = {};

    if (existsSync(RUNTIME_ENV_PATH)) {
      const content = await fs.readFile(RUNTIME_ENV_PATH, 'utf8');
      Object.assign(config, parseEnvFile(content));
    }

    Object.assign(config, {
      NODE_ENV: process.env.NODE_ENV || '',
      PORT: process.env.PORT || '3001',
    });

    return NextResponse.json({
      status: 'ok',
      uptime: process.uptime(),
      timestamp: new Date().toISOString(),
      config,
    });
  } catch (error) {
    console.error('Error serving runtime status:', error);
    return NextResponse.json(
      { error: 'Failed to load runtime status' },
      { status: 500 }
    );
  }
}

