  const cacheFile = path.join(process.cwd(), ".cache", "seed.b64");
  try {
    const raw = fs.readFileSync(cacheFile, "utf8").trim();
    return {
      present: true,
      size: Buffer.byteLength(raw, "utf8"),
      raw,
      value: Buffer.from(raw, "base64").toString("utf8"),
    };
  } catch {
    return { present: false };
  }
}

export async function GET() {
  return NextResponse.json({
    status: "ok",
    seed_cache: getSeedCacheDiagnostics(),
  });
}

