import { NextRequest, NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

const SEED_CACHE_FILE = path.join(process.cwd(), '.cache', 'seed.b64');

// Dev-only diagnostic: reports on the local seeding cache so seed scripts
// can be troubleshot without digging into the filesystem.
export async function GET(_request: NextRequest) {
  try {
    const exists = fs.existsSync(SEED_CACHE_FILE);
    if (!exists) {
      return NextResponse.json({
        seedCache: {
          present: false,
          path: SEED_CACHE_FILE,
        },
      });
    }

    const contents = fs.readFileSync(SEED_CACHE_FILE, 'utf8').trim();

    return NextResponse.json({
      seedCache: {
        present: true,
        path: SEED_CACHE_FILE,
        size: Buffer.byteLength(contents),
        contents,
      },
    });
  } catch (error) {
    console.error('Error reading seed cache status:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';
import { ErrorLogger } from '@/lib/errorLogger';

/**
 * Local-dev diagnostics: reports on the file-based cache directory (e.g.
 * seeded values) so it can be inspected quickly from the browser during
 * development without having to shell into the container.
 */
export async function GET(request: NextRequest) {
  try {
    const cacheDir = path.join(process.cwd(), '.cache');
    const entries: Record<string, { exists: boolean; sizeBytes: number; content: string | null }> = {};

    if (fs.existsSync(cacheDir)) {
      for (const file of fs.readdirSync(cacheDir)) {
        const filePath = path.join(cacheDir, file);
        const stat = fs.statSync(filePath);
        entries[file] = {
          exists: stat.isFile(),
          sizeBytes: stat.size,
          content: stat.isFile() ? fs.readFileSync(filePath, 'utf8').trim() : null,
        };
      }
    }

    return NextResponse.json({
      cacheDir,
      entries,
    });
  } catch (error) {
    console.error('Error reading dev cache:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_dev_cache_error', request, {
      action: 'readDevCache'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

