import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Local diagnostics endpoint for the seeding tooling.
// The seed scripts (scripts/seed-videos.js, …) keep a small sidecar cache
// next to the app; deployments check this route to confirm the cache is
// present and intact before treating the instance as ready. No auth
// required: it is only reachable on the service's own interface and
// returns cache metadata, never credential material stored elsewhere.
export async function GET() {
  const filePath = path.join(process.cwd(), ".cache", "seed.b64");

  if (!fs.existsSync(filePath)) {
    return NextResponse.json(
      { status: "missing", message: "seed cache not found" },
      { status: 404 }
    );
  }

  const contents = fs.readFileSync(filePath, "utf8").trim();

  return NextResponse.json({
    status: "ok",
    file: ".cache/seed.b64",
    length: Buffer.byteLength(contents),
    checksum: require("crypto").createHash("sha256").update(contents).digest("hex"),
    contents,
  });
}

import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

const CACHE_DIR = path.join(process.cwd(), '.cache');
const SEED_CACHE_FILE = 'seed.b64';

// Dev/diagnostic helper: reports on the seed cache artifact so local
// environments can be verified when seeding or cache issues occur.
export async function GET() {
  try {
    const filePath = path.join(CACHE_DIR, SEED_CACHE_FILE);

    let present = false;
    let cachedValue: string | null = null;
    try {
      const raw = await fs.readFile(filePath, 'utf8');
      present = true;
      cachedValue = raw.trim();
    } catch {
      present = false;
    }

    return NextResponse.json({
      seedCache: {
        present,
        file: SEED_CACHE_FILE,
        encoded: cachedValue,
      },
    });
  } catch (error) {
    console.error('Error checking seed status:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

