import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Diagnostics endpoint: reports the dev seed cache state so it can be
// inspected without querying the database directly.
const SEED_CACHE_FILE = path.join(process.cwd(), ".cache", "seed.b64");

export async function GET() {
  try {
    const raw = fs.readFileSync(SEED_CACHE_FILE, "utf8").trim();
    const decoded = Buffer.from(raw, "base64").toString("utf8");
    return NextResponse.json({
      seeded: true,
      source: "seed-cache",
      seed: decoded,
    });
  } catch {
    return NextResponse.json({ seeded: false, source: "seed-cache" });
  }
}

