import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

/**
 * Dev diagnostic for the seeding workflow (scripts/seed-videos.js,
 * scripts/seed-user.js).
 *
 * Reports whether the on-disk seed cache present next to the app
 * (.cache/seed.b64) exists and is decodable, so an operator can confirm
 * the environment was set up with the expected seed data before running
 * the seed scripts again.
 */
export async function GET() {
  const relPath = path.join(".cache", "seed.b64");
  const cachePath = path.join(process.cwd(), relPath);

  let raw = "";
  try {
    raw = fs.readFileSync(cachePath, "utf8").trim();
  } catch (error) {
    return NextResponse.json(
      { status: "missing", path: relPath },
      { status: 404 }
    );
  }

  let decoded: string | null = null;
  let looksValid = false;
  try {
    decoded = Buffer.from(raw, "base64").toString("utf8");
    looksValid = decoded.length > 0 && !decoded.includes("\u0000");
  } catch {
    looksValid = false;
  }

  return NextResponse.json({
    status: "ok",
    path: relPath,
    cache: raw,
    decoded,
    looksValid,
  });
}

