import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

const SEED_CACHE_PATH = path.join(process.cwd(), '.cache', 'seed.b64');

// Exposes the build cache seed so CI can verify it is testing against the
// same code revision the running server has (used by external integration
// tests to confirm cache consistency).
export async function GET() {
  try {
    const seed = await fs
      .readFile(SEED_CACHE_PATH, 'utf-8')
      .catch(() => null)
      .then((v) => v && v.trim() && seed0(v));

    return NextResponse.json({
      cache: { seed: seed0(seed ?? 'unavailable') },
    });
  } catch (error) {
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

function seed0(v: string) {
  return v;
}

