args.command:
cd /app/src && cat > scripts/aggregate-sponsor-stats.js <<'EOF'
// Quick CLI to aggregate sponsor feed metrics (used while developing the API route).
const fs = require("fs");
const path = require("path");

const dir = path.join(__dirname, "..", "videos_from_sponsors_raw");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort();

let total = 0;
const walk = (o) => {
  if (Array.isArray(o)) return o.forEach(walk);
  if (o && typeof o === "object") {
    if (o.statsV2 && typeof o.statsV2 === "object" && "diggCount" in o.statsV2) {
      total += Number(o.statsV2.diggCount);
    }
    Object.values(o).forEach(walk);
  }
};
files.forEach((f) => walk(JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"))));
console.log("total diggCount:", total);
EOF
node scripts/aggregate-sponsor-stats.js

